WITH cleaned AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, ROUND(amount, 1) AS amount_rounded, COALESCE(merchant, 'NONE') AS resolved_merchant FROM transactions WHERE merchant IS NOT NULL AND txn_time >= TO_DATE('2023-06-12')) SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, amount_rounded, resolved_merchant, AVG(amount) OVER (PARTITION BY account_id ORDER BY amount_rounded, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS amount_avg_5, CUME_DIST() OVER (ORDER BY amount_rounded DESC NULLS LAST) AS amount_rounded_cume_dist FROM cleaned;
